import{_ as e,o as a,c as i,a3 as t}from"./chunks/framework.DH50UWNB.js";const k=JSON.parse('{"title":"Install Wake","description":"Install the Wake server on Linux, macOS or Windows with WSL 2 with one command, in Docker, and find your Wake URL and installation directory.","frontmatter":{"description":"Install the Wake server on Linux, macOS or Windows with WSL 2 with one command, in Docker, and find your Wake URL and installation directory."},"headers":[],"relativePath":"start/install.md","filePath":"start/install.md","lastUpdated":1794486787000}'),n={name:"start/install.md"};function o(l,s,r,h,d,p){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="install-wake" tabindex="-1">Install Wake <a class="header-anchor" href="#install-wake" aria-label="Permalink to &quot;Install Wake&quot;">​</a></h1><p>Wake runs on one machine you own, in Docker: the server, the web app, its database and the storage for evidence files. One command installs all of it.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>Linux, macOS, or Windows with WSL 2 (<a href="#windows-with-wsl-2">below</a>), on an amd64 (x86-64) or arm64 machine.</li><li>Docker, running, with the Docker Compose v2 plugin.</li><li><code>curl</code>, and <code>ssh-keygen</code> from OpenSSH 8.1 or newer, which checks the release signature. macOS includes it; on Linux it is the <code>openssh-client</code> package.</li><li><code>sha256sum</code> or <code>shasum</code>, which checks each downloaded file against the signed list. Linux and macOS include one of them.</li><li>Node.js 24 or newer with npm, for the <code>wake</code> CLI. Without them the server still installs, and you add the CLI later.</li><li>A Git repository and a coding agent: <a href="/wake-dist/docs/agents/claude-code">Claude Code</a>, <a href="/wake-dist/docs/agents/opencode">OpenCode</a>, <a href="/wake-dist/docs/agents/pi">Pi</a> or <a href="/wake-dist/docs/agents/codex">Codex</a>.</li></ul><p>A plan in the repository, written with <a href="/wake-dist/docs/agents/openspec">OpenSpec</a>, <a href="/wake-dist/docs/agents/spec-kit">Spec Kit</a> or <a href="/wake-dist/docs/agents/odd">ODD</a>, is optional: you can connect first and let your agent write the plan later. The installer checks what it needs before it writes anything; <a href="/wake-dist/docs/run/install-options">Install options</a> lists every requirement and option.</p><h2 id="install-the-server" tabindex="-1">Install the server <a class="header-anchor" href="#install-the-server" aria-label="Permalink to &quot;Install the server&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/dalodev/wake-dist/releases/latest/download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>The command downloads the newest release, checks its signature and installs it into your installation directory. Once Wake answers, the installer also:</p><ul><li>turns on daily upgrades: every day at 04:17, machine time, it backs up Wake and upgrades the server and the web app (see <a href="/wake-dist/docs/run/upgrade">Upgrade</a>),</li><li>puts <code>wake-server</code> on your <code>PATH</code>, the command that starts, stops, upgrades, backs up and restores Wake,</li><li>installs the <code>wake</code> CLI when Node.js 24 or newer and npm are present,</li><li>remembers this installation, so the <code>wake</code> commands you run on this machine find it by themselves,</li><li>opens your browser on the page where you create your account.</li></ul><p>It ends with a checklist of what it set up and where Wake is running, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Wake 2.4.0 installer</span></span>
<span class="line"><span>  ✓ Docker is running</span></span>
<span class="line"><span>  ✓ Ports 8080 and 8081 are free</span></span>
<span class="line"><span>  ✓ Secrets generated in /home/you/wake-server/.env (never printed)</span></span>
<span class="line"><span>  ✓ Server, web, database and storage started</span></span>
<span class="line"><span>  ✓ License: Wake Free License, in /home/you/wake-server/LICENSE</span></span>
<span class="line"><span>  ✓ wake CLI 2.4.0 installed</span></span>
<span class="line"><span>  ✓ wake-server added to your PATH</span></span>
<span class="line"><span>  ✓ Daily upgrades on: 04:17, backup first, rollback if unhealthy</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Wake is running at http://localhost:8080</span></span>
<span class="line"><span>  → Your browser is opening. Create your account there.</span></span>
<span class="line"><span>    Didn&#39;t open? Visit http://localhost:8080/sign-up yourself.</span></span>
<span class="line"><span>  → Then, in your project&#39;s git repository: wake setup</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Manage it with wake-server start, stop, status, upgrade, backup, restore, accounts, auto-upgrade and install-cli (/home/you/wake-server/wake-server).</span></span></code></pre></div><p>A line starting with <code>!</code> names a step it could not do and the command that does it later, such as <code>wake-server install-cli</code> once Node.js is installed.</p><h2 id="your-wake-url-and-installation-directory" tabindex="-1">Your Wake URL and installation directory <a class="header-anchor" href="#your-wake-url-and-installation-directory" aria-label="Permalink to &quot;Your Wake URL and installation directory&quot;">​</a></h2><p><strong>Your Wake URL</strong> is the address of your Wake: you open the web app there, and the CLI and your agents connect to it. It is <code>http://localhost:8080</code> by default. The installer&#39;s <code>--port</code> option serves it on another port, and <code>--domain</code> serves it at <code>https://&lt;your domain&gt;</code>. Evidence files use a second address that the installer also sets up (<code>http://localhost:8081</code> by default, <code>https://s3.&lt;your domain&gt;</code> with <code>--domain</code>); you never need to type it.</p><p><strong>Your installation directory</strong> holds Wake&#39;s settings, its backups and the <code>wake-server</code> command. It is <code>~/wake-server</code> by default; <code>--dir</code> chooses another.</p><p>Options go after <code>sh -s --</code>, for example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/dalodev/wake-dist/releases/latest/download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9090</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/wake</span></span></code></pre></div><p>The rest of these docs write <code>&lt;your Wake URL&gt;</code> and <code>&lt;your installation directory&gt;</code>: use your own wherever you see them.</p><h2 id="who-can-reach-it" tabindex="-1">Who can reach it <a class="header-anchor" href="#who-can-reach-it" aria-label="Permalink to &quot;Who can reach it&quot;">​</a></h2><p>A local installation, the default, answers only on this machine: it listens on <code>127.0.0.1</code>, so no other computer on your network reaches it. You, your browser and the agents on this machine use it at <code>http://localhost:8080</code>.</p><p>For teammates on other machines, install Wake with <code>--domain</code> on a server they can reach. It serves Wake over HTTPS at your domain (see <a href="/wake-dist/docs/run/install-options">Install options</a>). A local installation cannot be shared through a tunnel of your own: its addresses, including the one evidence files use, stay <code>localhost</code>, and the CLI sends its token only to an <code>https</code> address or to <code>localhost</code>. The free plan allows up to 3 people in all, however many installations you run, and agents never count.</p><h2 id="windows-with-wsl-2" tabindex="-1">Windows with WSL 2 <a class="header-anchor" href="#windows-with-wsl-2" aria-label="Permalink to &quot;Windows with WSL 2&quot;">​</a></h2><p>On Windows, Wake runs inside Ubuntu on WSL 2, Windows&#39; built-in Linux. Follow these steps in order. Each says where to run its commands: in PowerShell on Windows, or in the Ubuntu terminal.</p><h3 id="_1-install-wsl-2-and-ubuntu" tabindex="-1">1. Install WSL 2 and Ubuntu <a class="header-anchor" href="#_1-install-wsl-2-and-ubuntu" aria-label="Permalink to &quot;1. Install WSL 2 and Ubuntu&quot;">​</a></h3><p>Open PowerShell as administrator (right-click <strong>Start</strong>, then <strong>Terminal (Admin)</strong>) and run:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wsl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install</span></span></code></pre></div><p>Restart Windows when it asks. Ubuntu then opens and asks for a user name and a password: they are your Linux account, and <code>sudo</code> asks for that password later. To check, run in PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wsl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">list </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose</span></span></code></pre></div><p>It lists <code>Ubuntu</code> with <code>2</code> under <code>VERSION</code>.</p><h3 id="_2-install-docker-desktop" tabindex="-1">2. Install Docker Desktop <a class="header-anchor" href="#_2-install-docker-desktop" aria-label="Permalink to &quot;2. Install Docker Desktop&quot;">​</a></h3><p>Install <a href="https://docs.docker.com/desktop/features/wsl/" target="_blank" rel="noreferrer">Docker Desktop for Windows</a> and keep its WSL 2 option on. Open Docker Desktop, go to <strong>Settings</strong> &gt; <strong>Resources</strong> &gt; <strong>WSL Integration</strong>, turn on <strong>Ubuntu</strong>, and choose <strong>Apply &amp; restart</strong>. To check, run in the Ubuntu terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span></code></pre></div><p>It prints <code>Docker Compose version v2...</code>. Docker Desktop must be running whenever you use Wake.</p><h3 id="_3-install-the-tools-and-node-js" tabindex="-1">3. Install the tools and Node.js <a class="header-anchor" href="#_3-install-the-tools-and-node-js" aria-label="Permalink to &quot;3. Install the tools and Node.js&quot;">​</a></h3><p>In the Ubuntu terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openssh-client</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/nvm-sh/nvm/v0.40.3/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span>
<span class="line prompt"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bashrc</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nvm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span></span></code></pre></div><p>To check, run <code>node --version</code>: it prints <code>v24.</code> and the rest of the version. Install Node.js with nvm, as above, and not with <code>apt</code>: the installer puts the <code>wake</code> command in place with <code>npm install --global</code>, which needs no <code>sudo</code> with nvm.</p><h3 id="_4-install-wake" tabindex="-1">4. Install Wake <a class="header-anchor" href="#_4-install-wake" aria-label="Permalink to &quot;4. Install Wake&quot;">​</a></h3><p>In the Ubuntu terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/dalodev/wake-dist/releases/latest/download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>It ends with the checklist <a href="#install-the-server">above</a>, including <code>✓ wake CLI ... installed</code>.</p><h3 id="_5-open-wake-in-your-windows-browser" tabindex="-1">5. Open Wake in your Windows browser <a class="header-anchor" href="#_5-open-wake-in-your-windows-browser" aria-label="Permalink to &quot;5. Open Wake in your Windows browser&quot;">​</a></h3><p>Open <code>http://localhost:8080</code> in your Windows browser; WSL 2 forwards <code>localhost</code> to Ubuntu. If no browser opened by itself, copy the address the installer printed (the one with <code>/sign-up</code>) and create your account there.</p><h3 id="_6-connect-a-repository-and-run-your-agent" tabindex="-1">6. Connect a repository and run your agent <a class="header-anchor" href="#_6-connect-a-repository-and-run-your-agent" aria-label="Permalink to &quot;6. Connect a repository and run your agent&quot;">​</a></h3><p>Keep your repositories in Ubuntu&#39;s own folders and run your agent from the Ubuntu terminal, so its hooks find <code>wake</code>. In the Ubuntu terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/code</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/code</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">L</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line prompt"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repositor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre></div><p>Install your agent inside Ubuntu, following its own instructions, and start it from that folder. Then go on with <a href="/wake-dist/docs/start/first-project#sign-your-agent-in">Your first project</a>.</p><h3 id="daily-upgrades" tabindex="-1">Daily upgrades <a class="header-anchor" href="#daily-upgrades" aria-label="Permalink to &quot;Daily upgrades&quot;">​</a></h3><p>Daily upgrades run at 04:17 from Ubuntu&#39;s <code>cron</code>, so only while Ubuntu is running. To check that <code>cron</code> runs, in the Ubuntu terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is-active</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cron</span></span></code></pre></div><p>It prints <code>active</code>. If it prints something else, or <code>systemctl</code> fails, turn on systemd, which starts <code>cron</code> with Ubuntu (see <a href="https://learn.microsoft.com/windows/wsl/wsl-config" target="_blank" rel="noreferrer">WSL&#39;s settings</a>):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;[boot]\\nsystemd=true\\n&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/wsl.conf</span></span></code></pre></div><p>Then run <code>wsl --shutdown</code> in PowerShell and open Ubuntu again. Whenever you want, upgrade by hand in the Ubuntu terminal with <code>wake-server upgrade</code>; see <a href="/wake-dist/docs/run/upgrade">Upgrade</a>.</p><h3 id="where-the-cli-keeps-its-token" tabindex="-1">Where the CLI keeps its token <a class="header-anchor" href="#where-the-cli-keeps-its-token" aria-label="Permalink to &quot;Where the CLI keeps its token&quot;">​</a></h3><p>Ubuntu on WSL usually has no keychain service, so the CLI keeps its token in a file only you can read; see <a href="/wake-dist/docs/reference/security#tokens-on-your-machine">Tokens on your machine</a>.</p><h2 id="run-it-again" tabindex="-1">Run it again <a class="header-anchor" href="#run-it-again" aria-label="Permalink to &quot;Run it again&quot;">​</a></h2><p>Running the installer again changes nothing in the installation and opens Wake; the options only apply to a new installation. One machine keeps one Wake: the installer refuses a second installation in another directory and names the existing one.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="/wake-dist/docs/start/cli">Install the CLI and sign in</a>. If the installer already installed the CLI, you can go straight to <a href="/wake-dist/docs/start/first-project">Your first project</a>: <code>wake setup</code> signs you in.</p>`,59)])])}const u=e(n,[["render",o]]);export{k as __pageData,u as default};
